package com.example.taskmanager.repository; import com.example.taskmanager.model.*; import org.springframework.data.jpa.repository.*; import java.time.LocalDateTime; import java.util.*;
public interface TaskRepository extends JpaRepository<Task,Long>{ List<Task> findByUserIdOrderByPriorityScoreDesc(Long userId); List<Task> findByUserIdAndDeadlineBetweenAndReminderSentFalse(Long userId,LocalDateTime a,LocalDateTime b); long countByUserId(Long id); long countByUserIdAndStatus(Long id,String status); long countByUserIdAndDeadlineBeforeAndStatusNot(Long id,LocalDateTime now,String status); }
